INSERT INTO `places` VALUES
(1,'Sungai Kenanga','Wisata','Wisata Alam','Aliran sungai di batas selatan desa. Warga menyusuri sungai dengan perahu kayu, memancing, atau menikmati senja dari dermaga BUMDes.','Batas selatan desa','0812 3450 1107','Sewa perahu Rp 10.000','07.00–18.00',27,1,'Tampil','2026-11-20 14:16:13'),
(2,'Hamparan Persawahan','Wisata','Agrowisata','Sawah seluas 580 hektare yang menghijau sepanjang musim tanam. Tersedia paket belajar menanam dan memanen padi bersama petani.','RW 01 – RW 02','0812 3450 1108','Gratis (paket edukasi Rp 25.000)','Setiap hari',24,1,'Tampil','2026-11-20 14:16:13'),
(3,'Perkebunan Desa','Wisata','Agrowisata','Kebun terluas di wilayah desa, mencakup 1.950 hektare. Pengunjung bisa berkeliling kebun buah dan belajar budidaya bersama kelompok tani.','RW 03',NULL,'Gratis','07.00–16.00',12,1,'Tampil','2026-11-20 14:16:13'),
(4,'Taman Desa','Wisata','Ruang Publik','Ruang santai untuk keluarga di dekat Kantor Desa, dengan area bermain anak, bangku taman, dan jalur jalan kaki yang teduh.','Dekat Kantor Desa',NULL,'Gratis','06.00–21.00',28,1,'Tampil','2026-11-20 14:16:13'),
(5,'Bukit Pandang Senja','Wisata','Alam','Bukit kecil di sisi timur desa dengan pemandangan sawah dan kebun yang luas. Paling indah saat matahari terbenam.','RT 08 / RW 02',NULL,'Gratis','Setiap hari',4,0,'Tampil','2026-11-20 14:16:13'),
(6,'Jalur Sepeda Lingkar Sawah','Wisata','Olahraga','Rute sepeda sepanjang 7 km mengelilingi sawah dan kebun. Ramai pesepeda setiap Minggu pagi.','Start di Balai Desa',NULL,'Gratis','Minggu, 06.00–09.00',26,0,'Tampil','2026-11-20 14:16:13'),
(7,'Beras Organik','UMKM','Pertanian','Beras organik hasil sawah kelompok Tani Maju yang ditanam tanpa pestisida kimia. Pulen, wangi, dan dikemas karung 5 kg dan 10 kg.','RT 03 / RW 01','0812 3450 1101','Rp 15.000/kg','Setiap hari, 07.00–17.00',2,1,'Tampil','2026-11-20 14:16:13'),
(8,'Anyaman Warga','UMKM','Kerajinan','Tas, tikar, dan keranjang dari rotan dan purun buatan kelompok perajin Anyaman Mulya. Sudah dipasarkan sampai Pangkalan Bun.','RT 02 / RW 01','0812 3450 1103','Rp 45.000','08.00–16.00',1,1,'Tampil','2026-11-20 14:16:13'),
(9,'Hasil Kebun Segar','UMKM','Pertanian','Sayur dan buah segar langsung dari kebun warga: cabai, tomat, terong, pisang, dan buah musiman. Bisa pesan antar di dalam desa.','Galeri UMKM BUMDes','0812 3450 1110','Rp 20.000/kg','07.00–15.00',25,1,'Tampil','2026-11-20 14:16:13'),
(10,'Warung Sari Rasa','UMKM','Kuliner','Warung makan rumahan dengan menu nasi sayur, ikan bakar sungai, dan sambal khas Bu Sari. Favorit pekerja kebun saat makan siang.','RT 01 / RW 01','0812 3450 1102','Rp 12.000–25.000','07.00–20.00',31,0,'Tampil','2026-11-20 14:16:13'),
(11,'Keripik Pisang Bu Rina','UMKM','Kuliner','Keripik pisang kepok renyah rasa original, manis, dan balado dari pisang kebun warga.','RT 06 / RW 02','0812 3450 1104','Rp 10.000/bungkus','08.00–17.00',13,0,'Tampil','2026-11-20 14:16:13'),
(12,'Madu Kelulut Marga Lestari','UMKM','Pertanian','Madu lebah kelulut yang dibudidayakan di pinggir hutan desa, dipanen langsung oleh peternak binaan BUMDes.','RT 10 / RW 03','0812 3450 1105','Rp 85.000/botol','Pemesanan via WA',14,0,'Tampil','2026-11-20 14:16:13'),
(13,'Festival Panen Raya','Budaya','Acara Tahunan','Perayaan syukur setelah panen padi setiap bulan Juni: pawai hasil bumi, lomba masak, bazar UMKM, dan pentas seni warga.','Lapangan Desa',NULL,'Gratis','Setiap Juni',6,0,'Tampil','2026-11-20 14:16:13'),
(14,'Sanggar Seni Karang Taruna','Budaya','Kesenian','Wadah anak muda belajar tari kreasi, musik, dan teater. Latihan rutin setiap Sabtu sore dan tampil di acara desa.','Balai Desa','0812 3450 1109','Gratis','Sabtu, 15.00–17.00',23,0,'Tampil','2026-11-20 14:16:13'),
(15,'Permainan Tradisional Anak','Budaya','Tradisi','Kegiatan rutin mengenalkan engklek, egrang, dan layang-layang kepada anak-anak.','Lapangan RW 02',NULL,'Gratis','Minggu sore',20,0,'Tampil','2026-11-20 14:16:13'),
(16,'Jumat Bersih Gotong Royong','Budaya','Tradisi','Kebiasaan warga membersihkan saluran air, jalan, dan fasilitas umum bersama setiap Jumat pagi di pekan pertama.','Seluruh RT',NULL,'Gratis','Jumat pekan pertama',8,0,'Tampil','2026-11-20 14:16:13');
